CREATE      VIEW [synapse_fo].[vwBudgetTransactionLine]
AS

	SELECT 

		l.[recid]
		,l.[linenumber]
		,l.[createdon]
		,l.[createdby]
		,l.[modifiedon]
		,l.[modifiedby]
		,CAST(l.[date] AS DATE) AS [Budget Date]

		,l.[dataareaid]
		,l.[quantity]
		,l.[price]
		,l.[taxgroup]
		,l.[budgettransactionheader]
		,l.[comment]
		,l.[accountingcurrencyamount]
		,l.[transactioncurrencyamount]
		,l.[transactioncurrency]
		,enbt.[MemberName] AS [Amount Type]
		,dac.[MainAccountValue] AS [Main Account]
		,dac.[COSTCENTERVALUE] AS [Cost Centre]
		,dac.[PROJECTVALUE] AS [Project]
		,dac.[PRODUCTCODEVALUE] AS [Product Code]
		,dac.[PRODUCTGROUPVALUE] AS [Product Group]
		,dac.[EVENTVALUE] AS [Event]
		,dac.[COUNTRYVALUE] AS [Country]
		,dh.[Name] AS [Account Structure]

	,CASE
		WHEN MAC.ACCOUNTCATEGORY = 'AAAA' AND (dac.[PRODUCTCODEVALUE] IS NULL OR dac.[PRODUCTCODEVALUE] NOT IN ('RAFEE_ACAND', 'RAFEE_APCC','RAFEE_ASSOC','RAFEE_FRICS','RAFEE_MRICS','RAFEE_PMU2')) THEN 10001 --Subscription Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAB' THEN 10002 --Elections & Enrolments

		WHEN MAC.ACCOUNTCATEGORY = 'AAAC' AND dac.[COSTCENTERVALUE] NOT IN (6010, 6020) THEN 10003 --Commercial Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAR' THEN 10004 --Regulation Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAA' AND dac.[PRODUCTCODEVALUE] IN ('RAFEE_ACAND', 'RAFEE_APCC','RAFEE_ASSOC','RAFEE_FRICS','RAFEE_MRICS','RAFEE_PMU2') then 10005 --Readmission Fees
		WHEN MAC.ACCOUNTCATEGORY = 'AAAS' AND ma.MAINACCOUNTID = 000000 THEN 10001 --Surcharges is removed and moved to Subscriptions (2025-01-08 16:30)
		WHEN MAC.ACCOUNTCATEGORY = 'AAAC' AND dac.[COSTCENTERVALUE] IN (6010, 6020) THEN 10007 --SBE Income

		WHEN MAC.ACCOUNTCATEGORY = 'CA' AND (dac.[COSTCENTERVALUE] NOT BETWEEN 4000 AND 4370) AND (dac.[COSTCENTERVALUE] NOT BETWEEN 4410 AND 4430) AND (dac.[COSTCENTERVALUE] NOT BETWEEN 4510 AND 4520) THEN 10101 --Commercial (CoS)
		WHEN MAC.ACCOUNTCATEGORY = 'CA' AND dac.[COSTCENTERVALUE] BETWEEN 4410 AND 4430 THEN 10102 --Elections & Enrolments (CoS)
		WHEN MAC.ACCOUNTCATEGORY = 'CA' AND ((dac.[COSTCENTERVALUE] BETWEEN 4000 AND 4370) OR (dac.[COSTCENTERVALUE] BETWEEN 4510 AND 4520)) THEN 10103 --Standards & Regulation
		WHEN MAC.ACCOUNTCATEGORY = 'CC' THEN 10104 --Credit Cards
		WHEN MAC.ACCOUNTCATEGORY = 'CBD' THEN 10105 --Bad Debt Provision

		WHEN MAC.ACCOUNTCATEGORY = 'DPC' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10201 --Payroll Cost
		WHEN MAC.ACCOUNTCATEGORY = 'DTC' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10202 --Temps/Contractors
		WHEN MAC.ACCOUNTCATEGORY = 'DOTB' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10203 --Staff Travel & Team Building
		WHEN MAC.ACCOUNTCATEGORY = 'DOEI' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10204 --Staff Development/Wellbeing
		WHEN (MAC.ACCOUNTCATEGORY = 'DXFE' AND dac.[PROJECTVALUE] IS NULL) OR (MAC.ACCOUNTCATEGORY = 'DXFE' AND dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%') THEN 10205 --Bonus Provision 
		WHEN MAC.ACCOUNTCATEGORY = 'DORE' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) AND ma.MAINACCOUNTID <> 000000 THEN 10206 --Recruitment Costs
		WHEN MAC.ACCOUNTCATEGORY = 'DORE' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) AND ma.MAINACCOUNTID = 000000 THEN 10404 --Governance Consultancy


		WHEN MAC.ACCOUNTCATEGORY = 'DOEP' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10301 --IT Costs
		WHEN MAC.ACCOUNTCATEGORY = 'DOER' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10302 --Office & Property Costs
		WHEN MAC.ACCOUNTCATEGORY = 'DOEO' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE]	   LIKE 'FAP%')) THEN 10303 --Insurance
		WHEN MAC.ACCOUNTCATEGORY = 'DOED' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10304 --Professional / Consultancy Fees
		WHEN MAC.ACCOUNTCATEGORY = 'DOEM' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10305 --Marketing
		WHEN MAC.ACCOUNTCATEGORY = 'DOEL' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10306 --Corporate Subscriptions
		WHEN MAC.ACCOUNTCATEGORY = 'DOEQ' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10307 --Legal Fees
		WHEN MAC.ACCOUNTCATEGORY = 'DOET' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10308 --Audit, Tax & Financial Compliance

		WHEN MAC.ACCOUNTCATEGORY = 'DOEG' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10309 --Research
		WHEN MAC.ACCOUNTCATEGORY = 'DOEH' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10310 --Sponsorship

		WHEN MAC.ACCOUNTCATEGORY = 'DOEK' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10311 --Catering
		WHEN MAC.ACCOUNTCATEGORY = 'DOEC' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10312 --Other Costs

		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND ma.MAINACCOUNTID  <> 000000 AND ma.MAINACCOUNTID  <> 000000 AND (dac.[PROJECTVALUE] IS NULL OR dac.[PROJECTVALUE] LIKE 'PRJ%' OR dac.[PROJECTVALUE] LIKE 'FAP%' OR (ma.MAINACCOUNTID = 000000 AND dac.[PROJECTVALUE] <> 'PRJ050')) AND dac.[PROJECTVALUE] NOT IN ('PRJ006','PRJ130','PRJ110', 'PRJ146', 'PRJ147', 'PRJ143', 'PRJ144', 'PRJ149', 'PRJ133', 'PRJ151', 'PRJ152', 'PRJ154', 'PRJ155', 'PRJ156', 'PRJ157', 'PRJ158', 'PRJ159', 'PRJ160', 'PRJ161', 'PRJ089', 'PRJ163', 'PRJ165', 'PRJ173', 'PRJ174', 'PRJ175', 'PRJ176', 'PRJ177', 'PRJ178', 'PRJ179', 'PRJ180', 'PRJ181', 'PRJ182', 'PRJ183', 'PRJ167', 'PRJ191', 'PRJ192', 'PRJ193', 'PRJ194', 'PRJ195', 'PRJ170', 'PRJ023', 'PRJ196', 'PRJ197', 'PRJ198') THEN 10501 --dac.[PROJECTVALUE]s

		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND ma.MAINACCOUNTID  <> 000000 AND ma.MAINACCOUNTID  <> 000000 AND dac.[PROJECTVALUE] IN ('PRJ163', 'PRJ165', 'PRJ173', 'PRJ174', 'PRJ175', 'PRJ176', 'PRJ177', 'PRJ178', 'PRJ179', 'PRJ180', 'PRJ181', 'PRJ182', 'PRJ183', 'PRJ167', 'PRJ191', 'PRJ192', 'PRJ193', 'PRJ194', 'PRJ195', 'PRJ023', 'PRJ170', 'PRJ196', 'PRJ197', 'PRJ198', 'PRJ151') THEN 10717 --Strategic Investments , Other dac.[PROJECTVALUE]s

		WHEN (MAC.ACCOUNTCATEGORY = 'DWRB' OR (MAC.ACCOUNTCATEGORY = 'DOMC' AND (dac.[COSTCENTERVALUE] BETWEEN 1000 AND 1150 OR dac.[COSTCENTERVALUE] BETWEEN 1310 AND 1380 OR dac.[COSTCENTERVALUE] BETWEEN 1600 AND 1720))) THEN 10313 --WRB Engagement

		WHEN MAC.ACCOUNTCATEGORY = 'DXFC' AND (dac.[PROJECTVALUE] IS NULL OR dac.[PROJECTVALUE] NOT IN ('PRJ006','PRJ050','PRJ144','PRJ151')) THEN 10314 --Depreciation & Amortisation

		WHEN MAC.ACCOUNTCATEGORY = 'DXFC' AND dac.[PROJECTVALUE] IN ('PRJ006','PRJ050','PRJ144','PRJ151') THEN 10702 --Strategic Depreciation 
		WHEN MAC.ACCOUNTCATEGORY = 'DOEN' THEN 10315 --IFMA Service Fee

		
		WHEN MAC.ACCOUNTCATEGORY = 'DOMC' AND NOT (dac.[COSTCENTERVALUE] BETWEEN 1000 AND 1150 OR dac.[COSTCENTERVALUE] BETWEEN 1310 AND 1380 OR dac.[COSTCENTERVALUE] BETWEEN 1600 AND 1720) 
			  AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10401 --Member Costs

		WHEN MAC.ACCOUNTCATEGORY = 'DOEA' AND ma.MAINACCOUNTID = 000000 THEN 10316 --Events, Raj Maddala, 2025-01-08 16:30 new category

		WHEN MAC.ACCOUNTCATEGORY = 'DOEA' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%') AND ma.MAINACCOUNTID <> 000000) THEN 10402 --External Conferences, Raj Maddala, 2025-01-08 16:30 excluded MAINACCOUNTID = 000000
		WHEN ma.MAINACCOUNTID = 000000 AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10403 --Non-Exec Fees

		WHEN MAC.ACCOUNTCATEGORY = 'DXFD' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10601 --Bank Charges
		WHEN MAC.ACCOUNTCATEGORY = 'DXFI' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10602 --Interest
		WHEN MAC.ACCOUNTCATEGORY = 'DXFL' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10603 --Taxation
		WHEN MAC.ACCOUNTCATEGORY = 'DXFX' THEN 10604 --FX Translation

		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] IN ('PRJ006', 'PRJ144') THEN 10701 --D365 dac.[PROJECTVALUE]
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ143' THEN 10703 --Data Enablement
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ133' THEN 10704 --Business Process Management
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ149' THEN 10705 --Commercialisation
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ152' THEN 10707 --Market & Strategy
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ154' THEN 10708 --Customer Service Experience
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ156' THEN 10709 --Organisational Design
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ155' THEN 10710 --Pipeline Growth
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ157' THEN 10711 --Member Experience
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ158' THEN 10712 --Dynamic Working
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ159' THEN 10713 --Sustainability
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ160' THEN 10714 --Governance
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] = 'PRJ161' THEN 10715 --Transformation Delivery
		WHEN ((ma.MAINACCOUNTID = 000000 AND (dac.[PROJECTVALUE] IS NULL OR dac.[PROJECTVALUE] NOT LIKE 'PRJ%'))
			OR (ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND dac.[PROJECTVALUE] IN ('PRJ130', 'PRJ110', 'PRJ146', 'PRJ147', 'PRJ089')))THEN 10716 --Post Review Costs
		WHEN MAC.ACCOUNTCATEGORY = 'DXFK' AND (dac.[PROJECTVALUE] IS NULL OR (dac.[PROJECTVALUE] NOT LIKE 'PRJ%' AND dac.[PROJECTVALUE] NOT LIKE 'FAP%')) THEN 10706 --Other
		WHEN MAC.ACCOUNTCATEGORY = 'DXFN' THEN 10802 --Net Investments
		WHEN MAC.ACCOUNTCATEGORY = 'DXFH' THEN 10803 --(Profit)/Loss on disposal of Investments --ADRIAN IGNORE OTHER DXFH MAIN ACCOUNTS (000000, 000000, 000000) FROM NET INVESTMENTS
		WHEN MAC.ACCOUNTCATEGORY = 'DOIC' THEN 10804 -- Intercompany Recharges--NEWLINE

		WHEN MAC.ACCOUNTCATEGORY = 'FAFA' THEN 20001 --Intangible Assets --NEWLINE
		WHEN MAC.ACCOUNTCATEGORY IN ('FAFPCO', 'FAFP') AND ma.MAINACCOUNTID <> 000000 THEN 20002 --Property, Plant & Equipment
		WHEN ma.MAINACCOUNTID = 000000 THEN 20003 --ROU Assets
		WHEN MAC.ACCOUNTCATEGORY = 'FAFS' THEN 20004 --Investments in Subsides & Assocs --NEWLINE
		WHEN ma.MAINACCOUNTID = 000000 THEN 20005 --Deferred Tax Asset
		WHEN MAC.ACCOUNTCATEGORY = 'LBPAOC' THEN 20006 --Pension Asset

		WHEN MAC.ACCOUNTCATEGORY = 'HCIN' THEN 20101 --Inventories
		WHEN MAC.ACCOUNTCATEGORY = 'FAFR' THEN 20102 --Available for Sale Investments
		WHEN MAC.ACCOUNTCATEGORY IN ('HCJRDB', 'HCJRAR', 'HCJRDPP') THEN 20103 --Trade & Other Recievables
		WHEN MAC.ACCOUNTCATEGORY = 'HCJX' THEN 20104 --Cash & Cash Equivalents

		WHEN MAC.ACCOUNTCATEGORY IN ('LBCT', 'LBCTVA') THEN 20201 --Current Tax Liabilities
		WHEN MAC.ACCOUNTCATEGORY IN ('LBAPAA', 'LBAPRL', 'LBPADF', 'LBPAAP', 'LBAPAP') AND ma.MAINACCOUNTID <> 000000 THEN 20202 --Trade & Other Payables
		WHEN ma.MAINACCOUNTID = 000000 THEN 20203 --ROU Liabilty

		WHEN MAC.ACCOUNTCATEGORY = 'JBDT' THEN 20301 --Deferred Tax
		WHEN MAC.ACCOUNTCATEGORY = 'JBPV' THEN 20302 --Provisions

		WHEN MAC.ACCOUNTCATEGORY = 'RVRSV' AND ma.MAINACCOUNTID <> 000000 THEN 20401 --Revaluation Reserves
		WHEN MAC.ACCOUNTCATEGORY = 'RVIN' THEN 20402 --Investment Reserves
		WHEN MAC.ACCOUNTCATEGORY = 'RVOT' THEN 20403 --Other Reserves
		WHEN ma.MAINACCOUNTID IN (000000, 000000)  THEN 20406-- Revenue Reserves

		--2026-08-20 16:30, Raj Maddala (Shifting the product codes)
		WHEN MAC.ACCOUNTCATEGORY = 'AAAO' AND dac.[PRODUCTCODEVALUE] NOT IN ('TDSGRANT','GEOSAASSESSMENT','GEOSAPROJINCEPTION','GEOSAWPONE','GEOSAWPTHREE','GEOSAWPTWO','GEOSAWPFOUR','GEOSAWPFIVE') THEN 10008 --GGS Restaurant Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAO' AND dac.[PRODUCTCODEVALUE] IN ('TDSGRANT','GEOSAASSESSMENT','GEOSAPROJINCEPTION','GEOSAWPONE','GEOSAWPTHREE','GEOSAWPTWO','GEOSAWPFOUR','GEOSAWPFIVE') THEN 10009 --Tenancy Deposit Scheme
		
		END AS 'TB_Category_Code'

	FROM [synapse_fo].[BUDGETTRANSACTIONLINE] l
		INNER JOIN [synapse_fo].[RetailEnumValueTable] enbt
			ON l.BudgetType = enbt.Value
			AND enbt.EnumName = 'BudgetType'
		LEFT JOIN [synapse_fo].[DimensionAttributeValueCombination] dac
			ON l.LedgerDimension = dac.RECID
		LEFT JOIN [synapse_fo].[DimensionHierarchy] dh
			ON dac.AccountStructure = dh.RECID
			AND dac.PARTITION = dh.PARTITION
		LEFT JOIN synapse_fo.MAINACCOUNT ma
			ON dac.mainaccountvalue = ma.mainaccountid

		LEFT JOIN [synapse_fo].[MAINACCOUNTCATEGORY] MAC
			ON MA.ACCOUNTCATEGORYREF = MAC.ACCOUNTCATEGORYREF
			AND MA.PARTITION = MAC.PARTITION
